// Adjusts the Android project generated by `npx cap add android` (run by
// .github/workflows/android.yml after `cap sync`, from app/):
//   1. edge-to-edge on every Android version, dark icons on the light page
//      (Android 15+ already forces edge-to-edge; older phones would show
//      plain bands above and below the app);
//   2. a white window background, seen while the page loads.
import fs from "fs";
import path from "path";

const main = "android/app/src/main";

function edit(file, change) {
  const before = fs.readFileSync(file, "utf8");
  const after = change(before);
  if (after === before) throw new Error(`android-patch: nothing changed in ${file}`);
  fs.writeFileSync(file, after);
}

function find(dir, name) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      const found = find(p, name);
      if (found) return found;
    } else if (entry.name === name) return p;
  }
  return null;
}

// 1. Edge-to-edge, transparent bars with dark icons (the app is light)
const activity = find(`${main}/java`, "MainActivity.java");
const pkg = fs.readFileSync(activity, "utf8").match(/^package ([\w.]+);/m)[1];
fs.writeFileSync(
  activity,
  `package ${pkg};

import android.graphics.Color;
import android.os.Bundle;
import androidx.activity.EdgeToEdge;
import androidx.activity.SystemBarStyle;
import com.getcapacitor.BridgeActivity;

public class MainActivity extends BridgeActivity {
    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this, SystemBarStyle.light(Color.TRANSPARENT, Color.TRANSPARENT), SystemBarStyle.light(Color.TRANSPARENT, Color.TRANSPARENT));
    }
}
`,
);
edit("android/app/build.gradle", (s) =>
  s.replace(
    /(\n\s*implementation "androidx\.appcompat:appcompat:[^"]+")/,
    `$1\n    implementation "androidx.activity:activity:$androidxActivityVersion"`,
  ),
);

// 2. White window background (the default follows the phone: black in dark mode)
fs.writeFileSync(
  `${main}/res/values/babelibris_colors.xml`,
  `<?xml version="1.0" encoding="utf-8"?>
<resources>
    <color name="glacify_background">#ffffff</color>
</resources>
`,
);
edit(`${main}/res/values/styles.xml`, (s) =>
  s.replace(
    /(<style name="AppTheme\.NoActionBar"[^>]*>)/,
    `$1\n        <item name="android:windowBackground">@color/glacify_background</item>`,
  ),
);

console.log(`android-patch: ${pkg}, edge-to-edge, light window`);
